mapper.select:
SELECT R.REQUEST_ID, R.REQUEST_NO, R.TITLE, R.IS_URGENT, R.REQUEST_CLASS, R.REQUEST_STATUS, R.APPROVAL_STATUS, R.CREATED_AT, R.DESIRED_DATE, ( SELECT COUNT(*) FROM QUERY_ITEM I WHERE I.REQUEST_ID = R.REQUEST_ID ) AS SQL_COUNT FROM QUERY_REQUEST R WHERE R.DRAFTER_ID = #{drafterId}
AND ( INSTR(UPPER(R.REQUEST_NO), UPPER(#{keyword})) > 0 OR INSTR(UPPER(R.TITLE), UPPER(#{keyword})) > 0 )
AND R.REQUEST_STATUS = #{status}
ORDER BY R.CREATED_AT DESC, R.REQUEST_ID DESC

SELECT REQUEST_STATUS
FROM QUERY_REQUEST
WHERE REQUEST_ID = #{requestId}
  AND DRAFTER_ID = #{drafterId}
FOR UPDATE

mapper.update:
UPDATE QUERY_REQUEST
SET TITLE = #{title},
    PURPOSE = #{purpose, jdbcType=CLOB},
    DETAIL_CONTENT = #{detailContent, jdbcType=CLOB},
    IS_URGENT = #{isUrgent},
    DESIRED_DATE = #{desiredDate, jdbcType=DATE}
WHERE REQUEST_ID = #{requestId}
  AND DRAFTER_ID = #{drafterId}
  AND REQUEST_STATUS = 'DRAFT'

mapper.delete:
DELETE FROM QUERY_ITEM
WHERE REQUEST_ID = #{requestId}
  AND EXISTS (
      SELECT 1
      FROM QUERY_REQUEST R
      WHERE R.REQUEST_ID = #{requestId}
        AND R.DRAFTER_ID = #{drafterId}
        AND R.REQUEST_STATUS = 'DRAFT'
  )

